1	//! Template registry for Bivvy.
2	//!
3	//! This module handles loading and resolving templates from multiple sources:
4	//! - Built-in templates (embedded in binary)
5	//! - User templates (~/.bivvy/templates/)
6	//! - Project templates (.bivvy/templates/)
7	//! - Remote templates (coming in M11)
8	//!
9	//! # Resolution Order
10	//!
11	//! Templates are resolved in this order (first match wins):
12	//! 1. Project-local
13	//! 2. User-local
14	//! 3. Remote (by priority)
15	//! 4. Built-in
16	//!
17	//! # Example
18	//!
19	//! ```
20	//! use bivvy::registry::Registry;
21	//!
22	//! // Load registry with built-in templates only
23	//! let registry = Registry::new(None).unwrap();
24	//!
25	//! // Get a built-in template
26	//! if let Some(template) = registry.get("yarn") {
27	//!     println!("Template: {}", template.name);
28	//! }
29	//! ```
30	
