1	//! Add command implementation.
2	//!
3	//! The `bivvy add` command adds a template step to an existing
4	//! `.bivvy/config.yml` file. It appends the step to the end of the
5	//! steps section and optionally adds it to a workflow.
6	
7	use std::fs;
8	use std::path::{Path, PathBuf};
9	
10	use crate::cli::args::AddArgs;
11	use crate::config::{load_config, load_merged_config, load_project_config};
12	use crate::error::{BivvyError, Result};
13	use crate::registry::resolver::Registry;
14	use crate::registry::template::Template;
15	use crate::ui::{hints, UserInterface};
16	
17	use super::dispatcher::{Command, CommandResult};
18	
19	/// The add command implementation.
20	pub struct AddCommand {
21	    project_root: PathBuf,
22	    args: AddArgs,
23	    config_override: Option<PathBuf>,
24	}
25	
26	impl AddCommand {
27	    /// Create a new add command.
28	    pub fn new(project_root: &Path, args: AddArgs) -> Self {
29	        Self {
30	            project_root: project_root.to_path_buf(),
31	            args,
32	            config_override: None,
33	        }
34	    }
35	
36	    /// Set an override config path.
37	    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
38	        self.config_override = config_override;
39	        self
40	    }
41	
42	    /// Get the project root path.
43	    pub fn project_root(&self) -> &Path {
44	        &self.project_root
45	    }
46	
47	    /// Get the command arguments.
48	    pub fn args(&self) -> &AddArgs {
49	        &self.args
50	    }
51	
52	    /// Format a step block for insertion into the config file.
53	    ///
54	    /// Produces the same format as `bivvy init` — a template reference
55	    /// with commented-out details showing what the template provides.
56	    fn format_step_block(step_name: &str, template_name: &str, template: &Template) -> String {
57	        let mut block = format!("  {}:\n    template: {}\n", step_name, template_name);
58	
59	        // Show command as comment
60	        if let Some(ref cmd) = template.step.command {
61	            block.push_str(&format!("    # command: {}\n", cmd));
62	        }
63	
64	        block
65	    }
66	
67	    /// Insert a step into the config file content (text-level editing).
68	    ///
69	    /// Appends the step block after the last step entry in the `steps:` section.
70	    fn insert_step_into_config(content: &str, step_block: &str) -> Result<String> {
71	        let lines: Vec<&str> = content.lines().collect();
72	        let mut result_lines: Vec<String> = Vec::new();
73	        let mut found_steps = false;
74	        let mut insert_index = None;
75	        let mut in_steps_section = false;
76	
77	        for line in lines.iter() {
78	            let trimmed = line.trim();
79	
80	            // Detect the `steps:` top-level key
81	            if trimmed == "steps:" && !line.starts_with(' ') && !line.starts_with('#') {
82	                found_steps = true;
83	                in_steps_section = true;
84	                result_lines.push(line.to_string());
85	                continue;
86	            }
87	
88	            if in_steps_section {
89	                // We're inside the steps section. A new top-level key
90	                // (non-indented, non-empty, non-comment) ends it.
91	                let is_top_level_key = !trimmed.is_empty()
92	                    && !trimmed.starts_with('#')
93	                    && !line.starts_with(' ')
94	                    && !line.starts_with('\t');
95	
96	                if is_top_level_key {
97	                    // Insert right before this line
98	                    insert_index = Some(result_lines.len());
99	                    in_steps_section = false;
100	                }
101	            }
102	
103	            result_lines.push(line.to_string());
104	        }
105	
106	        if !found_steps {
107	            return Err(BivvyError::ConfigValidationError {
108	                message: "No 'steps:' section found in config file".to_string(),
109	            });
110	        }
111	
112	        // If we never left the steps section, append at the end
113	        let idx = insert_index.unwrap_or(result_lines.len());
114	
115	        // Ensure there's a blank line before the new step block
116	        // when inserting at the boundary
117	        let step_block_with_newline = if idx < result_lines.len() {
118	            // Inserting before a top-level key — add trailing newline
119	            format!("{}\n", step_block)
120	        } else {
121	            // Appending at end
122	            format!("\n{}", step_block)
123	        };
124	
125	        result_lines.insert(idx, step_block_with_newline.trim_end().to_string());
126	
127	        let mut output = result_lines.join("\n");
128	        // Ensure file ends with newline
129	        if !output.ends_with('\n') {
130	            output.push('\n');
131	        }
132	        Ok(output)
133	    }
134	
135	    /// Add a step name to a workflow's steps list in the config file content.
136	    fn add_to_workflow(
137	        content: &str,
138	        workflow_name: &str,
139	        step_name: &str,
140	        after: Option<&str>,
141	    ) -> Result<String> {
142	        let lines: Vec<&str> = content.lines().collect();
143	
144	        // Find the target steps line
145	        let target = Self::find_workflow_steps_line(&lines, workflow_name);
146	
147	        if let Some((line_idx, prefix, current_steps)) = target {
148	            let new_steps = Self::insert_step_name(&current_steps, step_name, after);
149	            let mut result_lines: Vec<String> = lines.iter().map(|l| l.to_string()).collect();
150	            result_lines[line_idx] = format!("{}steps: [{}]", prefix, new_steps);
151	            let mut output = result_lines.join("\n");
152	            if !output.ends_with('\n') {
153	                output.push('\n');
154	            }
155	            Ok(output)
156	        } else {
157	            // Workflow not found — return content unchanged
158	            Ok(content.to_string())
159	        }
160	    }
161	
162	    /// Find the `steps: [...]` line for a given workflow name.
163	    ///
164	    /// Returns `(line_index, indentation_prefix, steps_content)` if found.
165	    fn find_workflow_steps_line(
166	        lines: &[&str],
167	        workflow_name: &str,
168	    ) -> Option<(usize, String, String)> {
169	        // Find `workflows:` top-level key
170	        let workflows_idx = lines.iter().enumerate().find_map(|(i, line)| {
171	            let trimmed = line.trim();
172	            if trimmed == "workflows:" && !line.starts_with(' ') && !line.starts_with('#') {
173	                Some(i)
174	            } else {
175	                None
176	            }
177	        })?;
178	
179	        // Find the specific workflow by name
180	        let workflow_pattern = format!("{}:", workflow_name);
181	        let mut workflow_idx = None;
182	        for (i, line) in lines.iter().enumerate().skip(workflows_idx + 1) {
183	            let trimmed = line.trim();
184	            if trimmed == workflow_pattern || trimmed.starts_with(&format!("{}: ", workflow_name)) {
185	                workflow_idx = Some(i);
186	                break;
187	            }
188	            // Stop at next top-level key
189	            if !trimmed.is_empty()
190	                && !trimmed.starts_with('#')
191	                && !line.starts_with(' ')
192	                && !line.starts_with('\t')
193	            {
194	                break;
195	            }
196	        }
197	
198	        let workflow_idx = workflow_idx?;
199	        let workflow_indent = lines[workflow_idx].len() - lines[workflow_idx].trim_start().len();
200	
201	        // Find the `steps:` line under this workflow
202	        for (i, line) in lines.iter().enumerate().skip(workflow_idx + 1) {
203	            let trimmed = line.trim();
204	            if trimmed.is_empty() || trimmed.starts_with('#') {
205	                continue;
206	            }
207	
208	            let current_indent = line.len() - trimmed.len();
209	
210	            // Stop if we hit a sibling or parent-level key
211	            if current_indent <= workflow_indent {
212	                break;
213	            }
214	
215	            if trimmed.starts_with("steps:") {
216	                let prefix = line[..line.len() - trimmed.len()].to_string();
217	                if let (Some(start), Some(end)) = (trimmed.find('['), trimmed.find(']')) {
218	                    let list_content = trimmed[start + 1..end].to_string();
219	                    return Some((i, prefix, list_content));
220	                }
221	            }
222	        }
223	
224	        None
225	    }
226	
227	    /// Insert a step name into a comma-separated list string.
228	    fn insert_step_name(current: &str, new_step: &str, after: Option<&str>) -> String {
229	        let steps: Vec<&str> = current
230	            .split(',')
231	            .map(|s| s.trim())
232	            .filter(|s| !s.is_empty())
233	            .collect();
234	
235	        let mut new_steps: Vec<String> = steps.iter().map(|s| s.to_string()).collect();
236	
237	        if let Some(after_step) = after {
238	            if let Some(pos) = new_steps.iter().position(|s| s == after_step) {
239	                new_steps.insert(pos + 1, new_step.to_string());
240	            } else {
241	                // --after target not found, append
242	                new_steps.push(new_step.to_string());
243	            }
244	        } else {
245	            new_steps.push(new_step.to_string());
246	        }
247	
248	        new_steps.join(", ")
249	    }
250	}
251	
252	impl Command for AddCommand {
253	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
254	        let config_path = self.project_root.join(".bivvy/config.yml");
255	
256	        // Validate config exists
257	        if !config_path.exists() {
258	            ui.error("No configuration found. Run 'bivvy init' first.");
259	            return Ok(CommandResult::failure(2));
260	        }
261	
262	        let template_name = &self.args.template;
263	
264	        // Load merged config first so we can honor `template_sources` when
265	        // resolving the template the user is asking for.
266	        let config = if let Some(ref override_path) = self.config_override {
267	            load_config(&self.project_root, Some(override_path))?
268	        } else {
269	            load_merged_config(&self.project_root)?
270	        };
271	
272	        // Build the registry, including remote sources when configured.
273	        let registry = if config.template_sources.is_empty() {
274	            Registry::new(Some(&self.project_root))?
275	        } else {
276	            Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)?
277	        };
278	
279	        // Validate template exists
280	        let template = registry
281	            .get(template_name)
282	            .ok_or_else(|| BivvyError::UnknownTemplate {
283	                name: template_name.clone(),
284	            })?;
285	
286	        // Determine step name
287	        let step_name = self
288	            .args
289	            .step_name
290	            .as_deref()
291	            .unwrap_or(template_name.as_str());
292	
293	        // Validate step doesn't already exist. We re-read the project-only
294	        // config here to detect collisions in `.bivvy/config.yml` itself
295	        // (rather than steps inherited from extends/user/local files, which
296	        // are merged but not actually written).
297	        let project_config = if let Some(ref override_path) = self.config_override {
298	            load_config(&self.project_root, Some(override_path))?
299	        } else {
300	            load_project_config(&self.project_root)?
301	        };
302	        if project_config.steps.contains_key(step_name) {
303	            ui.error(&format!(
304	                "Step '{}' already exists in configuration. Use a different name with --as.",
305	                step_name
306	            ));
307	            return Ok(CommandResult::failure(1));
308	        }
309	
310	        // Read the raw config file
311	        let content = fs::read_to_string(&config_path)?;
312	
313	        // Format the new step block
314	        let step_block = Self::format_step_block(step_name, template_name, template);
315	
316	        // Insert the step into the config
317	        let mut new_content = Self::insert_step_into_config(&content, &step_block)?;
318	
319	        // Add to workflow unless --no-workflow
320	        if !self.args.no_workflow {
321	            let workflow = self.args.workflow.as_deref().unwrap_or("default");
322	
323	            new_content = Self::add_to_workflow(
324	                &new_content,
325	                workflow,
326	                step_name,
327	                self.args.after.as_deref(),
328	            )?;
329	        }
330	
331	        // Write the updated config
332	        fs::write(&config_path, &new_content)?;
333	
334	        ui.success(&format!(
335	            "Added '{}' step using template '{}'",
336	            step_name, template_name
337	        ));
338	
339	        if !self.args.no_workflow {
340	            let workflow = self.args.workflow.as_deref().unwrap_or("default");
341	            ui.message(&format!("  Added to '{}' workflow", workflow));
342	        }
343	
344	        ui.show_hint(&hints::after_add(step_name));
345	
346	        Ok(CommandResult::success())
347	    }
348	}
