1	//! Step decision engine.
2	//!
3	//! The `evaluate_step()` function is the single entry point for the decision matrix.
4	//! It evaluates a step through the full hierarchy: resolve dependencies (recursive),
5	//! hard blocks, soft blocks, force, satisfaction, and prompt decisions.
6	
7	use std::collections::{HashMap, HashSet};
8	use std::path::Path;
9	
10	use crate::checks::evaluator::CheckEvaluator;
11	use crate::checks::CheckResult;
12	use crate::config::interpolation::InterpolationContext;
13	use crate::config::schema::StepOverride;
14	use crate::runner::decision::{BlockReason, SkipReason, StepDecision};
15	use crate::runner::satisfaction::{self, ComputedSatisfaction};
16	use crate::runner::RerunWindow;
17	use crate::snapshots::SnapshotStore;
18	use crate::state::satisfaction::{SatisfactionCache, SatisfactionRecord};
19	use crate::state::StateStore;
20	use crate::steps::ResolvedStep;
21	
22	/// Result of evaluating a step through the decision engine.
23	#[derive(Debug, Clone)]
24	pub struct EvaluationResult {
25	    /// The decision for this step.
26	    pub decision: StepDecision,
27	    /// Why the decision was made (human-readable).
28	    pub reason: String,
29	    /// Computed satisfaction details (if satisfaction was evaluated).
30	    pub satisfaction: Option<ComputedSatisfaction>,
31	}
32	
33	/// Context needed by the decision engine to evaluate steps.
34	pub struct EngineContext<'a> {
35	    /// All resolved steps in the workflow.
36	    pub steps: &'a HashMap<String, ResolvedStep>,
37	    /// Project root directory.
38	    pub project_root: &'a Path,
39	    /// Interpolation context for check evaluation.
40	    pub interpolation: &'a InterpolationContext,
41	    /// Snapshot store for change checks.
42	    pub snapshot_store: &'a mut SnapshotStore,
43	    /// State store for execution history.
44	    pub state: Option<&'a StateStore>,
45	    /// Per-step workflow overrides.
46	    pub step_overrides: &'a HashMap<String, StepOverride>,
47	    /// Steps forced to re-run via --force flag.
48	    pub force: &'a HashSet<String>,
49	    /// Whether every step in this workflow should be forced (--force-all).
50	    pub force_all: bool,
51	    /// Pre-evaluated named check results for cross-step refs.
52	    pub named_check_results: &'a HashMap<String, CheckResult>,
53	    /// Satisfaction cache (two-layer).
54	    pub satisfaction_cache: &'a mut SatisfactionCache,
55	    /// Steps that have already been evaluated this session (decision cache).
56	    /// Maps step name -> evaluation result.
57	    pub evaluated: HashMap<String, EvaluationResult>,
58	    /// Steps that failed execution (set by the orchestrator after execution).
59	    pub failed_steps: &'a HashSet<String>,
60	    /// Steps the user explicitly skipped.
61	    pub user_skipped_steps: &'a HashSet<String>,
62	    /// Steps confirmed as satisfied.
63	    pub satisfied_steps: &'a HashSet<String>,
64	    /// Steps with unresolved requirement gaps (after install attempts).
65	    /// The orchestrator populates this after attempting installation.
66	    pub unresolved_gaps: &'a HashSet<String>,
67	}
68	
69	/// Evaluate a step through the full decision matrix.
70	///
71	/// This is the single entry point for step decisions. It evaluates the step
72	/// through the hierarchy defined in the plan:
73	///
74	/// 1. Check decision cache (return early if already evaluated this session)
75	/// 2. Hard blocks (dependency failed/blocked, precondition failed)
76	/// 3. Force override → Run
77	/// 4. Compute satisfaction (satisfied_when > checks > rerun window)
78	/// 5. Satisfied → AutoSkip
79	/// 6. Not satisfied → sensitive? Prompt : confirm? Prompt : AutoRun
80	pub fn evaluate_step(step_name: &str, ctx: &mut EngineContext<'_>) -> EvaluationResult {
81	    // 1. Check decision cache
82	    if let Some(cached) = ctx.evaluated.get(step_name) {
83	        return cached.clone();
84	    }
85	
86	    let step = match ctx.steps.get(step_name) {
87	        Some(s) => s,
88	        None => {
89	            return EvaluationResult {
90	                decision: StepDecision::Block {
91	                    reason: BlockReason::DependencyFailed {
92	                        dependency: step_name.to_string(),
93	                    },
94	                },
95	                reason: format!("Step '{}' not found", step_name),
96	                satisfaction: None,
97	            };
98	        }
99	    };
100	
101	    // 2. Hard blocks — dependency failed
102	    if let Some(failed_dep) = step
103	        .depends_on
104	        .iter()
105	        .find(|dep| ctx.failed_steps.contains(*dep))
106	    {
107	        let result = EvaluationResult {
108	            decision: StepDecision::Block {
109	                reason: BlockReason::DependencyFailed {
110	                    dependency: failed_dep.clone(),
111	                },
112	            },
113	            reason: format!("dependency '{}' failed", failed_dep),
114	            satisfaction: None,
115	        };
116	        ctx.evaluated.insert(step_name.to_string(), result.clone());
117	        return result;
118	    }
119	
120	    // Hard block — dependency skipped and not satisfied
121	    if let Some(skipped_dep) = step
122	        .depends_on
123	        .iter()
124	        .find(|dep| ctx.user_skipped_steps.contains(*dep) && !ctx.satisfied_steps.contains(*dep))
125	    {
126	        let result = EvaluationResult {
127	            decision: StepDecision::Block {
128	                reason: BlockReason::DependencySkipped {
129	                    dependency: skipped_dep.clone(),
130	                },
131	            },
132	            reason: format!("dependency '{}' skipped and not satisfied", skipped_dep),
133	            satisfaction: None,
134	        };
135	        ctx.evaluated.insert(step_name.to_string(), result.clone());
136	        return result;
137	    }
138	
139	    // Hard block — precondition fails
140	    if let Some(precondition) = step.execution.effective_precondition() {
141	        let mut evaluator =
142	            CheckEvaluator::new(ctx.project_root, ctx.interpolation, ctx.snapshot_store);
143	        let precond_result = evaluator.evaluate(&precondition);
144	        if !precond_result.passed_check() {
145	            let result = EvaluationResult {
146	                decision: StepDecision::Block {
147	                    reason: BlockReason::PreconditionFailed {
148	                        description: precond_result.description.clone(),
149	                    },
150	                },
151	                reason: format!("precondition failed: {}", precond_result.description),
152	                satisfaction: None,
153	            };
154	            ctx.evaluated.insert(step_name.to_string(), result.clone());
155	            return result;
156	        }
157	    }
158	
159	    // 3. Soft blocks — unresolved requirement gaps (install already attempted)
160	    if ctx.unresolved_gaps.contains(step_name) {
161	        let result = EvaluationResult {
162	            decision: StepDecision::Skip {
163	                reason: SkipReason::RequirementNotMet,
164	            },
165	            reason: "requirement not met".to_string(),
166	            satisfaction: None,
167	        };
168	        ctx.evaluated.insert(step_name.to_string(), result.clone());
169	        return result;
170	    }
171	
172	    // 4. Force override
173	    if ctx.force_all || ctx.force.contains(step_name) || step.behavior.force {
174	        let result = EvaluationResult {
175	            decision: StepDecision::Run,
176	            reason: "forced".to_string(),
177	            satisfaction: None,
178	        };
179	        ctx.evaluated.insert(step_name.to_string(), result.clone());
180	        return result;
181	    }
182	
183	    // 4. Compute satisfaction
184	    let rerun_window = resolve_effective_rerun_window(step, step_name, ctx.step_overrides);
185	    let last_success = ctx.state.and_then(|s| {
186	        let step_state = s.get_step(step_name)?;
187	        if step_state.status == crate::state::StepStatus::Success {
188	            step_state.last_run
189	        } else {
190	            None
191	        }
192	    });
193	
194	    let mut evaluator =
195	        CheckEvaluator::new(ctx.project_root, ctx.interpolation, ctx.snapshot_store);
196	
197	    let computed = satisfaction::compute_satisfaction(
198	        step,
199	        &mut evaluator,
200	        ctx.named_check_results,
201	        step_name,
202	        &rerun_window,
203	        last_success,
204	    );
205	
206	    // 5. Satisfied → AutoSkip (or Prompt if rerun with prompt_on_rerun)
207	    if computed.satisfied {
208	        // Store in satisfaction cache
209	        let record = SatisfactionRecord {
210	            satisfied: true,
211	            source: computed.source.clone(),
212	            recorded_at: chrono::Utc::now(),
213	            evidence: computed.evidence.clone(),
214	            config_hash: None,
215	            step_hash: None,
216	        };
217	        ctx.satisfaction_cache.store(step_name, record);
218	
219	        // Check prompt_on_rerun: if satisfied via execution history and
220	        // prompt_on_rerun is true, prompt the user instead of auto-skipping.
221	        let is_rerun =
222	            computed.source == crate::state::satisfaction::SatisfactionSource::ExecutionHistory;
223	        let prompt_rerun =
224	            super::decision::effective_prompt_on_rerun(step, step_name, ctx.step_overrides);
225	
226	        if is_rerun && prompt_rerun {
227	            let result = EvaluationResult {
228	                decision: StepDecision::Prompt {
229	                    prompt_key: format!("rerun_{}", step_name),
230	                },
231	                reason: computed.description.clone(),
232	                satisfaction: Some(computed),
233	            };
234	            ctx.evaluated.insert(step_name.to_string(), result.clone());
235	            return result;
236	        }
237	
238	        let result = EvaluationResult {
239	            decision: StepDecision::Skip {
240	                reason: SkipReason::AutoSatisfied,
241	            },
242	            reason: computed.description.clone(),
243	            satisfaction: Some(computed),
244	        };
245	        ctx.evaluated.insert(step_name.to_string(), result.clone());
246	        return result;
247	    }
248	
249	    // 6. Not satisfied — determine how to proceed
250	    // Sensitive steps always prompt
251	    if step.behavior.sensitive {
252	        let result = EvaluationResult {
253	            decision: StepDecision::Prompt {
254	                prompt_key: format!("sensitive_{}", step_name),
255	            },
256	            reason: "sensitive step requires confirmation".to_string(),
257	            satisfaction: Some(computed),
258	        };
259	        ctx.evaluated.insert(step_name.to_string(), result.clone());
260	        return result;
261	    }
262	
263	    // Confirm steps always prompt
264	    if step.behavior.confirm {
265	        let result = EvaluationResult {
266	            decision: StepDecision::Prompt {
267	                prompt_key: format!("confirm_{}", step_name),
268	            },
269	            reason: "step requires confirmation".to_string(),
270	            satisfaction: Some(computed),
271	        };
272	        ctx.evaluated.insert(step_name.to_string(), result.clone());
273	        return result;
274	    }
275	
276	    // auto_run: false → prompt before running
277	    let effective_auto_run =
278	        super::decision::effective_auto_run(step, step_name, ctx.step_overrides);
279	    if !effective_auto_run {
280	        let result = EvaluationResult {
281	            decision: StepDecision::Prompt {
282	                prompt_key: format!("autorun_{}", step_name),
283	            },
284	            reason: "auto_run disabled — awaiting user confirmation".to_string(),
285	            satisfaction: Some(computed),
286	        };
287	        ctx.evaluated.insert(step_name.to_string(), result.clone());
288	        return result;
289	    }
290	
291	    // Default: auto-run
292	    let result = EvaluationResult {
293	        decision: StepDecision::AutoRun,
294	        reason: computed.description.clone(),
295	        satisfaction: Some(computed),
296	    };
297	    ctx.evaluated.insert(step_name.to_string(), result.clone());
298	    result
299	}
300	
301	/// Resolve the effective rerun window for a step, considering overrides.
302	fn resolve_effective_rerun_window(
303	    step: &ResolvedStep,
304	    step_name: &str,
305	    step_overrides: &HashMap<String, StepOverride>,
306	) -> RerunWindow {
307	    // Check for workflow-level override
308	    if let Some(override_cfg) = step_overrides.get(step_name) {
309	        if let Some(ref window_str) = override_cfg.rerun_window {
310	            if let Ok(w) = window_str.parse() {
311	                return w;
312	            }
313	        }
314	    }
315	    // Use the step's resolved rerun window
316	    step.behavior.rerun_window.clone()
317	}
