1	//! Satisfaction cache types and persistence.
2	//!
3	//! The satisfaction cache is the core data structure of bivvy's decision engine.
4	//! It records what bivvy knows about each step's satisfaction state — whether the
5	//! step's purpose is already fulfilled — and persists that knowledge across sessions.
6	//!
7	//! # Two-Layer Architecture
8	//!
9	//! The cache operates at two layers:
10	//! - **Persisted layer** (`satisfaction.json`): survives across sessions
11	//! - **Runtime layer** (in-memory `HashMap`): working copy for one session
12	//!
13	//! The runtime layer is seeded from the persisted layer on startup, updated as
14	//! steps are evaluated, and flushed back to disk at the end.
15	
16	use std::collections::HashMap;
17	use std::path::{Path, PathBuf};
18	
19	use chrono::{DateTime, Utc};
20	use serde::{Deserialize, Serialize};
21	
22	/// A persisted record of a step's satisfaction state.
23	///
24	/// Contains the satisfaction decision, the signal that produced it, and the
25	/// verifiable evidence that supports it. Used for both runtime decisions and
26	/// cross-session persistence.
27	#[derive(Debug, Clone, Serialize, Deserialize)]
28	pub struct SatisfactionRecord {
29	    /// Whether the step is satisfied.
30	    pub satisfied: bool,
31	
32	    /// What signal produced the satisfaction (or lack thereof).
33	    pub source: SatisfactionSource,
34	
35	    /// When this record was created or last updated.
36	    pub recorded_at: DateTime<Utc>,
37	
38	    /// The specific evidence that supports this record.
39	    /// Used for fast cross-session validation.
40	    pub evidence: SatisfactionEvidence,
41	
42	    /// Hash of the step's check configuration at the time of recording.
43	    /// If the config changes, this record is invalidated.
44	    #[serde(default, skip_serializing_if = "Option::is_none")]
45	    pub config_hash: Option<String>,
46	
47	    /// Hash of the step's definition (command, deps, tools) at recording time.
48	    /// If the definition changes, this record is invalidated.
49	    #[serde(default, skip_serializing_if = "Option::is_none")]
50	    pub step_hash: Option<String>,
51	}
