53	/// What signal produced a satisfaction decision.
54	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
55	pub enum SatisfactionSource {
56	    /// A file or binary exists at the expected path.
57	    PresenceCheck,
58	    /// Target hash matches baseline — nothing changed since last run.
59	    ChangeCheck,
60	    /// A check command succeeded.
61	    ExecutionCheck,
62	    /// Explicit `satisfied_when` conditions passed.
63	    ExplicitCondition,
64	    /// Step ran successfully within the rerun window.
65	    ExecutionHistory,
66	    /// No data yet — step has never been evaluated.
67	    NeverEvaluated,
68	}
