70	/// The verifiable evidence behind a satisfaction decision.
71	///
72	/// Each variant carries enough data to re-validate cheaply across sessions.
73	/// Presence checks need a stat(), change checks need a hash compare,
74	/// execution history needs a timestamp check.
75	#[derive(Debug, Clone, Serialize, Deserialize)]
76	pub enum SatisfactionEvidence {
77	    /// File or binary exists at this path.
78	    /// Validate: `stat()` the path.
79	    Presence { target: String, kind: PresenceKind },
80	
81	    /// Target hash matches baseline.
82	    /// Validate: rehash the target, compare.
83	    ChangeBaseline { target: String, hash: String },
84	
85	    /// Command exited 0.
86	    /// Validate: re-run the command (expensive — only for execution checks).
87	    CommandSuccess { command: String },
88	
89	    /// Step ran successfully at this time.
90	    /// Validate: check if `ran_at` is within the rerun window.
91	    HistoricalRun {
92	        ran_at: DateTime<Utc>,
93	        exit_code: i32,
94	    },
95	
96	    /// Multiple pieces of evidence (for `satisfied_when` with multiple conditions).
97	    Composite(Vec<SatisfactionEvidence>),
98	
99	    /// No evidence (step has never been evaluated).
100	    None,
101	}
