103	/// Kind of presence evidence.
104	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
105	pub enum PresenceKind {
106	    /// A file path exists.
107	    File,
108	    /// A binary is found on PATH.
109	    Binary,
110	    /// A custom command check.
111	    Custom,
112	}
113	
114	impl SatisfactionEvidence {
115	    /// Validate this evidence against the current state of the world.
116	    ///
117	    /// Returns `true` if the evidence still holds. Validation cost varies by type:
118	    /// - `Presence` — stat() call (~microseconds)
119	    /// - `ChangeBaseline` — rehash + compare (~milliseconds)
120	    /// - `HistoricalRun` — timestamp arithmetic (instant)
121	    /// - `CommandSuccess` — requires re-running the command (expensive, returns false to force re-evaluation)
122	    /// - `Composite` — validates each sub-evidence
123	    /// - `None` — always invalid
124	    pub fn validate(&self, project_root: &Path) -> bool {
125	        match self {
126	            SatisfactionEvidence::Presence { target, kind } => match kind {
127	                PresenceKind::File => {
128	                    let path = if Path::new(target).is_absolute() {
129	                        std::path::PathBuf::from(target)
130	                    } else {
131	                        project_root.join(target)
132	                    };
133	                    path.exists()
134	                }
135	                PresenceKind::Binary => {
136	                    // Check if binary is on PATH
137	                    crate::sys::find_on_path(target).is_some()
138	                }
139	                PresenceKind::Custom => {
140	                    // Custom presence checks can't be cheaply validated
141	                    false
142	                }
143	            },
144	            SatisfactionEvidence::ChangeBaseline { .. } => {
145	                // Rehashing requires the snapshot store — defer to the caller
146	                // For now, return false to force re-evaluation
147	                false
148	            }
149	            SatisfactionEvidence::CommandSuccess { .. } => {
150	                // Re-running a command is expensive — always re-evaluate
151	                false
152	            }
153	            SatisfactionEvidence::HistoricalRun { ran_at, exit_code } => {
154	                // Valid if the run succeeded (exit 0) — the rerun window check
155	                // is done by the caller since it depends on step configuration
156	                *exit_code == 0 && *ran_at <= Utc::now()
157	            }
158	            SatisfactionEvidence::Composite(evidence_list) => {
159	                evidence_list.iter().all(|e| e.validate(project_root))
160	            }
161	            SatisfactionEvidence::None => false,
162	        }
163	    }
164	}
