166	/// Two-layer satisfaction cache: persisted JSON on disk + runtime HashMap in memory.
167	///
168	/// During a `bivvy run`:
169	/// 1. Load persisted records from `satisfaction.json`
170	/// 2. As steps are evaluated, store results in the runtime layer
171	/// 3. At the end (or after each step for crash recovery), flush to disk
172	///
173	/// The runtime layer takes precedence over the persisted layer.
174	pub struct SatisfactionCache {
175	    /// Runtime layer — the working copy for this session.
176	    runtime: HashMap<String, SatisfactionRecord>,
177	    /// Persisted layer — loaded from disk at session start.
178	    persisted: HashMap<String, SatisfactionRecord>,
179	    /// Path to the satisfaction.json file.
180	    path: PathBuf,
181	}
182	
183	impl SatisfactionCache {
184	    /// Create an empty cache (for new projects or `--fresh` mode).
185	    pub fn empty(path: PathBuf) -> Self {
186	        Self {
187	            runtime: HashMap::new(),
188	            persisted: HashMap::new(),
189	            path,
190	        }
191	    }
192	
193	    /// Load the cache from a `satisfaction.json` file.
194	    ///
195	    /// If the file doesn't exist or is invalid, returns an empty cache.
196	    pub fn load(path: PathBuf) -> Self {
197	        let persisted = if path.exists() {
198	            match std::fs::read_to_string(&path) {
199	                Ok(content) => serde_json::from_str(&content).unwrap_or_default(),
200	                Err(_) => HashMap::new(),
201	            }
202	        } else {
203	            HashMap::new()
204	        };
205	
206	        Self {
207	            runtime: HashMap::new(),
208	            persisted,
209	            path,
210	        }
211	    }
212	
213	    /// Get a satisfaction record for a step.
214	    ///
215	    /// Checks the runtime layer first, then the persisted layer.
216	    /// Persisted records are validated before being returned — if the evidence
217	    /// is stale or the config/step hash doesn't match, the record is discarded.
218	    pub fn get(
219	        &self,
220	        step: &str,
221	        project_root: &Path,
222	        config_hash: Option<&str>,
223	        step_hash: Option<&str>,
224	    ) -> Option<&SatisfactionRecord> {
225	        // Runtime layer takes precedence — no validation needed (just computed)
226	        if let Some(record) = self.runtime.get(step) {
227	            return Some(record);
228	        }
229	
230	        // Check persisted layer with validation
231	        if let Some(record) = self.persisted.get(step) {
232	            // Structural invalidation: config or step definition changed
233	            if let Some(expected) = config_hash {
234	                if record.config_hash.as_deref() != Some(expected) {
235	                    return None;
236	                }
237	            }
238	            if let Some(expected) = step_hash {
239	                if record.step_hash.as_deref() != Some(expected) {
240	                    return None;
241	                }
242	            }
243	
244	            // Evidence validation
245	            if record.evidence.validate(project_root) {
246	                return Some(record);
247	            }
248	        }
249	
250	        None
251	    }
252	
253	    /// Get a satisfaction record from the runtime layer only (no validation).
254	    pub fn get_runtime(&self, step: &str) -> Option<&SatisfactionRecord> {
255	        self.runtime.get(step)
256	    }
257	
258	    /// Store a satisfaction record in the runtime layer.
259	    pub fn store(&mut self, step: &str, record: SatisfactionRecord) {
260	        self.runtime.insert(step.to_string(), record);
261	    }
262	
263	    /// Check if a step has any record (runtime or persisted, without validation).
264	    pub fn has_record(&self, step: &str) -> bool {
265	        self.runtime.contains_key(step) || self.persisted.contains_key(step)
266	    }
267	
268	    /// Invalidate a specific step's records from both layers.
269	    pub fn invalidate(&mut self, step: &str) {
270	        self.runtime.remove(step);
271	        self.persisted.remove(step);
272	    }
273	
274	    /// Invalidate all records (for `--fresh` mode).
275	    pub fn invalidate_all(&mut self) {
276	        self.runtime.clear();
277	        self.persisted.clear();
278	    }
279	
280	    /// Flush the runtime cache to disk as `satisfaction.json`.
281	    ///
282	    /// Merges runtime records into persisted records (runtime wins on conflict),
283	    /// then writes the combined result to disk using atomic write.
284	    pub fn flush(&mut self) -> std::io::Result<()> {
285	        // Merge runtime into persisted
286	        for (step, record) in &self.runtime {
287	            self.persisted.insert(step.clone(), record.clone());
288	        }
289	
290	        // Ensure parent directory exists
291	        if let Some(parent) = self.path.parent() {
292	            std::fs::create_dir_all(parent)?;
293	        }
294	
295	        // Atomic write: temp file then rename
296	        let content =
297	            serde_json::to_string_pretty(&self.persisted).map_err(std::io::Error::other)?;
298	        let temp_path = self.path.with_extension("json.tmp");
299	        std::fs::write(&temp_path, &content)?;
300	        std::fs::rename(&temp_path, &self.path)?;
301	
302	        Ok(())
303	    }
304	
305	    /// Get the path to the satisfaction.json file.
306	    pub fn path(&self) -> &Path {
307	        &self.path
308	    }
309	
310	    /// Get the number of records in the runtime layer.
311	    pub fn runtime_len(&self) -> usize {
312	        self.runtime.len()
313	    }
314	
315	    /// Get the number of records in the persisted layer.
316	    pub fn persisted_len(&self) -> usize {
317	        self.persisted.len()
318	    }
319	}
