/// Write `data` to `path` atomically by writing to a sibling temp file then renaming.
///
/// On Unix, `rename(2)` is atomic within the same filesystem — a concurrent
/// reader will see either the old content or the new content, never a partial write.
/// The temp file name includes the process ID to avoid collisions between
/// concurrent processes writing the same cache entry.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let temp_name = format!(
        "{}.{}.tmp",
        path.file_name().unwrap_or_default().to_string_lossy(),
        std::process::id()
    );
    let temp_path = path.with_file_name(temp_name);
    fs::write(&temp_path, data)
        .with_context(|| format!("Failed to write temp file {:?}", temp_path))?;
    fs::rename(&temp_path, path).with_context(|| {
        // Clean up temp file on rename failure
        let _ = fs::remove_file(&temp_path);
        format!("Failed to rename {:?} to {:?}", temp_path, path)
    })?;
    Ok(())
}

